AcpiDsCreateOperands (
ACPI_WALK_STATE         *WalkState,
ACPI_PARSE_OBJECT       *FirstArg)
{
ACPI_STATUS             Status = AE_OK;
ACPI_PARSE_OBJECT       *Arg;
ACPI_PARSE_OBJECT       *Arguments[ACPI_OBJ_NUM_OPERANDS];
UINT32                  ArgCount = 0;
UINT32                  Index = WalkState->NumOperands;
UINT32                  i;


ACPI_FUNCTION_TRACE_PTR (DsCreateOperands, FirstArg);


/* Get all arguments in the list */

Arg = FirstArg;
while (Arg)
{
if (Index >= ACPI_OBJ_NUM_OPERANDS)
{
return_ACPI_STATUS (AE_BAD_DATA);
}

Arguments[Index] = Arg;
WalkState->Operands [Index] = NULL;

/* Move on to next argument, if any */

Arg = Arg->Common.Next;
ArgCount++;
Index++;
}

ACPI_DEBUG_PRINT ((ACPI_DB_DISPATCH,
"NumOperands %d, ArgCount %d, Index %d\n",
WalkState->NumOperands, ArgCount, Index));

/* Create the interpreter arguments, in reverse order */

Index--;
for (i = 0; i < ArgCount; i++)
{
Arg = Arguments[Index];
WalkState->OperandIndex = (UINT8) Index;

Status = AcpiDsCreateOperand (WalkState, Arg, Index);
if (ACPI_FAILURE (Status))
{
goto Cleanup;
}

ACPI_DEBUG_PRINT ((ACPI_DB_DISPATCH,
"Created Arg #%u (%p) %u args total\n",
Index, Arg, ArgCount));
Index--;
}

return_ACPI_STATUS (Status);


Cleanup:
/*
* We must undo everything done above; meaning that we must
* pop everything off of the operand stack and delete those
* objects
*/
    AcpiDsObjStackPopAndDelete (ArgCount, WalkState);

ACPI_EXCEPTION ((AE_INFO, Status, "While creating Arg %u", Index));
return_ACPI_STATUS (Status);
}

my_object_increment_val (MyObject *obj, GError **error)
{
  obj->val++;
  return TRUE;
}

UWORD32 ihevcd_cabac_decode_bypass_bins_egk(cab_ctxt_t *ps_cabac,
bitstrm_t *ps_bitstrm,
WORD32 k)
{

UWORD32 u4_sym;
WORD32 numones;
WORD32 bin;

/* Sanity checks */
ASSERT((k >= 0));


numones = k;
bin = 1;
u4_sym = 0;
    while(bin)
{
IHEVCD_CABAC_DECODE_BYPASS_BIN(bin, ps_cabac, ps_bitstrm);
u4_sym += bin << numones++;
}

numones -= 1;
    numones = CLIP3(numones, 0, 16);

if(numones)
{
UWORD32 u4_suffix;

IHEVCD_CABAC_DECODE_BYPASS_BINS(u4_suffix, ps_cabac, ps_bitstrm, numones);
u4_sym += u4_suffix;
}
return (u4_sym);
}

