}

*pHandle = (effect_handle_t) module;

ALOGV("DownmixLib_Create() %p , size %zu", module, sizeof(downmix_module_t));

return 0;
}

error::Error GLES2DecoderImpl::HandleGetUniformfv(uint32 immediate_data_size,
const void* cmd_data) {
const gles2::cmds::GetUniformfv& c =
*static_cast<const gles2::cmds::GetUniformfv*>(cmd_data);
GLuint program = c.program;
GLint fake_location = c.location;
GLuint service_id;
GLint real_location = -1;
Error error;
typedef cmds::GetUniformfv::Result Result;
Result* result;
GLenum result_type;
  if (GetUniformSetup(
      program, fake_location, c.params_shm_id, c.params_shm_offset,
      &error, &real_location, &service_id,
      reinterpret_cast<void**>(&result), &result_type)) {
if (result_type == GL_BOOL || result_type == GL_BOOL_VEC2 ||
result_type == GL_BOOL_VEC3 || result_type == GL_BOOL_VEC4) {
      GLsizei num_values = result->GetNumResults();
scoped_ptr<GLint[]> temp(new GLint[num_values]);
glGetUniformiv(service_id, real_location, temp.get());
GLfloat* dst = result->GetData();
for (GLsizei ii = 0; ii < num_values; ++ii) {
dst[ii] = (temp[ii] != 0);
}
} else {
glGetUniformfv(service_id, real_location, result->GetData());
}
}
return error;
}

t42_parse_sfnts( T42_Face    face,
T42_Loader  loader )
{
T42_Parser  parser = &loader->parser;
FT_Memory   memory = parser->root.memory;
FT_Byte*    cur;
FT_Byte*    limit  = parser->root.limit;
FT_Error    error;
FT_Int      num_tables = 0;
    FT_ULong    count, ttf_size = 0;

FT_Long     n, string_size, old_string_size, real_size;
FT_Byte*    string_buf = NULL;
FT_Bool     allocated  = 0;

T42_Load_Status  status;


/* The format is                                */
/*                                              */
/*   /sfnts [ <hexstring> <hexstring> ... ] def */
/*                                              */
/* or                                           */
/*                                              */
/*   /sfnts [                                   */
/*      <num_bin_bytes> RD <binary data>        */
/*      <num_bin_bytes> RD <binary data>        */
/*      ...                                     */
/*   ] def                                      */
/*                                              */
/* with exactly one space after the `RD' token. */

T1_Skip_Spaces( parser );

if ( parser->root.cursor >= limit || *parser->root.cursor++ != '[' )
{
FT_ERROR(( "t42_parse_sfnts: can't find begin of sfnts vector\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}

T1_Skip_Spaces( parser );
status          = BEFORE_START;
string_size     = 0;
old_string_size = 0;
count           = 0;

while ( parser->root.cursor < limit )
{
cur = parser->root.cursor;

if ( *cur == ']' )
{
parser->root.cursor++;
goto Exit;
}

else if ( *cur == '<' )
{
T1_Skip_PS_Token( parser );
if ( parser->root.error )
goto Exit;

/* don't include delimiters */
string_size = (FT_Long)( ( parser->root.cursor - cur - 2 + 1 ) / 2 );
if ( FT_REALLOC( string_buf, old_string_size, string_size ) )
goto Fail;

allocated = 1;

parser->root.cursor = cur;
(void)T1_ToBytes( parser, string_buf, string_size, &real_size, 1 );
old_string_size = string_size;
string_size = real_size;
}

else if ( ft_isdigit( *cur ) )
{
if ( allocated )
{
FT_ERROR(( "t42_parse_sfnts: "
"can't handle mixed binary and hex strings\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}

string_size = T1_ToInt( parser );
if ( string_size < 0 )
{
FT_ERROR(( "t42_parse_sfnts: invalid string size\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}

T1_Skip_PS_Token( parser );             /* `RD' */
if ( parser->root.error )
return;

string_buf = parser->root.cursor + 1;   /* one space after `RD' */

if ( limit - parser->root.cursor < string_size )
{
          FT_ERROR(( "t42_parse_sfnts: too many binary data\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}
else
parser->root.cursor += string_size + 1;
}

if ( !string_buf )
{
FT_ERROR(( "t42_parse_sfnts: invalid data in sfnts array\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}

/* A string can have a trailing zero (odd) byte for padding. */
/* Ignore it.                                                */
if ( ( string_size & 1 ) && string_buf[string_size - 1] == 0 )
string_size--;

if ( !string_size )
{
FT_ERROR(( "t42_parse_sfnts: invalid string\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}

for ( n = 0; n < string_size; n++ )
{
switch ( status )
{
case BEFORE_START:
/* load offset table, 12 bytes */
if ( count < 12 )
{
face->ttf_data[count++] = string_buf[n];
continue;
}
else
{
            num_tables = 16 * face->ttf_data[4] + face->ttf_data[5];
            status     = BEFORE_TABLE_DIR;
            ttf_size   = 12 + 16 * num_tables;

            if ( FT_REALLOC( face->ttf_data, 12, ttf_size ) )
goto Fail;
}
/* fall through */

case BEFORE_TABLE_DIR:
/* the offset table is read; read the table directory */
          if ( count < ttf_size )
{
face->ttf_data[count++] = string_buf[n];
continue;
}
else
{
int       i;
FT_ULong  len;


for ( i = 0; i < num_tables; i++ )
{
FT_Byte*  p = face->ttf_data + 12 + 16 * i + 12;


len = FT_PEEK_ULONG( p );

/* Pad to a 4-byte boundary length */
              ttf_size += ( len + 3 ) & ~3;
}

            status         = OTHER_TABLES;
            face->ttf_size = ttf_size;

/* there are no more than 256 tables, so no size check here */
if ( FT_REALLOC( face->ttf_data, 12 + 16 * num_tables,
                             ttf_size + 1 ) )
goto Fail;
}
/* fall through */

case OTHER_TABLES:
/* all other tables are just copied */
          if ( count >= ttf_size )
{
            FT_ERROR(( "t42_parse_sfnts: too many binary data\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}
}
face->ttf_data[count++] = string_buf[n];
}
}

T1_Skip_Spaces( parser );
}

int main(int argc, char **argv)
{
#ifdef sgi
char tmpline[80];
#endif
char *p;
int rc, alen, flen;
int error = 0;
int have_bg = FALSE;
double LUT_exponent; /* just the lookup table */
double CRT_exponent = 2.2; /* just the monitor */
double default_display_exponent; /* whole display system */
XEvent e;
KeySym k;


displayname = (char *)NULL;
filename = (char *)NULL;


/* First set the default value for our display-system exponent, i.e.,
* the product of the CRT exponent and the exponent corresponding to
* the frame-buffer's lookup table (LUT), if any.  This is not an
* exhaustive list of LUT values (e.g., OpenStep has a lot of weird
* ones), but it should cover 99% of the current possibilities. */

#if defined(NeXT)
LUT_exponent = 1.0 / 2.2;
/*
if (some_next_function_that_returns_gamma(&next_gamma))
LUT_exponent = 1.0 / next_gamma;
*/
#elif defined(sgi)
LUT_exponent = 1.0 / 1.7;
/* there doesn't seem to be any documented function to get the
* "gamma" value, so we do it the hard way */
infile = fopen("/etc/config/system.glGammaVal", "r");
if (infile) {
double sgi_gamma;

fgets(tmpline, 80, infile);
fclose(infile);
sgi_gamma = atof(tmpline);
if (sgi_gamma > 0.0)
LUT_exponent = 1.0 / sgi_gamma;
}
#elif defined(Macintosh)
LUT_exponent = 1.8 / 2.61;
/*
if (some_mac_function_that_returns_gamma(&mac_gamma))
LUT_exponent = mac_gamma / 2.61;
*/
#else
LUT_exponent = 1.0; /* assume no LUT:  most PCs */
#endif

/* the defaults above give 1.0, 1.3, 1.5 and 2.2, respectively: */
default_display_exponent = LUT_exponent * CRT_exponent;


/* If the user has set the SCREEN_GAMMA environment variable as suggested
* (somewhat imprecisely) in the libpng documentation, use that; otherwise
* use the default value we just calculated.  Either way, the user may
* override this via a command-line option. */

if ((p = getenv("SCREEN_GAMMA")) != NULL)
display_exponent = atof(p);
else
display_exponent = default_display_exponent;


/* Now parse the command line for options and the PNG filename. */

while (*++argv && !error) {
if (!strncmp(*argv, "-display", 2)) {
if (!*++argv)
++error;
else
displayname = *argv;
} else if (!strncmp(*argv, "-gamma", 2)) {
if (!*++argv)
++error;
else {
display_exponent = atof(*argv);
if (display_exponent <= 0.0)
++error;
}
} else if (!strncmp(*argv, "-bgcolor", 2)) {
if (!*++argv)
++error;
else {
bgstr = *argv;
if (strlen(bgstr) != 7 || bgstr[0] != '#')
++error;
else
have_bg = TRUE;
}
} else {
if (**argv != '-') {
filename = *argv;
if (argv[1]) /* shouldn't be any more args after filename */
++error;
} else
++error; /* not expecting any other options */
}
}

if (!filename)
++error;


/* print usage screen if any errors up to this point */

if (error) {
fprintf(stderr, "\n%s %s:  %s\n", PROGNAME, VERSION, appname);
readpng_version_info();
fprintf(stderr, "\n"

"Usage:  %s [-display xdpy] [-gamma exp] [-bgcolor bg] file.png\n"
"    xdpy\tname of the target X display (e.g., ``hostname:0'')\n"
"    exp \ttransfer-function exponent (``gamma'') of the display\n"
          "\t\t  system in floating-point format (e.g., ``%.1f''); equal\n"
"\t\t  to the product of the lookup-table exponent (varies)\n"
"\t\t  and the CRT exponent (usually 2.2); must be positive\n"
"    bg  \tdesired background color in 7-character hex RGB format\n"
"\t\t  (e.g., ``#ff7700'' for orange:  same as HTML colors);\n"
"\t\t  used with transparent images\n"
"\nPress Q, Esc or mouse button 1 (within image window, after image\n"
          "is displayed) to quit.\n"
          "\n", PROGNAME, default_display_exponent);
exit(1);
}


if (!(infile = fopen(filename, "rb"))) {
fprintf(stderr, PROGNAME ":  can't open PNG file [%s]\n", filename);
++error;
} else {
if ((rc = readpng_init(infile, &image_width, &image_height)) != 0) {
switch (rc) {
case 1:
fprintf(stderr, PROGNAME
":  [%s] is not a PNG file: incorrect signature\n",
filename);
break;
case 2:
fprintf(stderr, PROGNAME
":  [%s] has bad IHDR (libpng longjmp)\n", filename);
break;
case 4:
fprintf(stderr, PROGNAME ":  insufficient memory\n");
break;
default:
fprintf(stderr, PROGNAME
":  unknown readpng_init() error\n");
break;
}
++error;
} else {
display = XOpenDisplay(displayname);
if (!display) {
readpng_cleanup(TRUE);
fprintf(stderr, PROGNAME ":  can't open X display [%s]\n",
displayname? displayname : "default");
++error;
}
}
if (error)
fclose(infile);
}


if (error) {
fprintf(stderr, PROGNAME ":  aborting.\n");
exit(2);
}


/* set the title-bar string, but make sure buffer doesn't overflow */

alen = strlen(appname);
flen = strlen(filename);
if (alen + flen + 3 > 1023)
sprintf(titlebar, "%s:  ...%s", appname, filename+(alen+flen+6-1023));
else
sprintf(titlebar, "%s:  %s", appname, filename);


/* if the user didn't specify a background color on the command line,
* check for one in the PNG file--if not, the initialized values of 0
* (black) will be used */

if (have_bg) {
unsigned r, g, b; /* this approach quiets compiler warnings */

sscanf(bgstr+1, "%2x%2x%2x", &r, &g, &b);
bg_red   = (uch)r;
bg_green = (uch)g;
bg_blue  = (uch)b;
} else if (readpng_get_bgcolor(&bg_red, &bg_green, &bg_blue) > 1) {
readpng_cleanup(TRUE);
fprintf(stderr, PROGNAME
":  libpng error while checking for background color\n");
exit(2);
}


/* do the basic X initialization stuff, make the window and fill it
* with the background color */

if (rpng_x_create_window())
exit(2);


/* decode the image, all at once */

Trace((stderr, "calling readpng_get_image()\n"))
image_data = readpng_get_image(display_exponent, &image_channels,
&image_rowbytes);
Trace((stderr, "done with readpng_get_image()\n"))


/* done with PNG file, so clean up to minimize memory usage (but do NOT
* nuke image_data!) */

readpng_cleanup(FALSE);
fclose(infile);

if (!image_data) {
fprintf(stderr, PROGNAME ":  unable to decode PNG image\n");
exit(3);
}


/* display image (composite with background if requested) */

Trace((stderr, "calling rpng_x_display_image()\n"))
if (rpng_x_display_image()) {
free(image_data);
exit(4);
}
Trace((stderr, "done with rpng_x_display_image()\n"))


/* wait for the user to tell us when to quit */

printf(
"Done.  Press Q, Esc or mouse button 1 (within image window) to quit.\n");
fflush(stdout);

do
XNextEvent(display, &e);
while (!(e.type == ButtonPress && e.xbutton.button == Button1) &&
!(e.type == KeyPress && /*  v--- or 1 for shifted keys */
((k = XLookupKeysym(&e.xkey, 0)) == XK_q || k == XK_Escape) ));


/* OK, we're done:  clean up all image and X resources and go away */


rpng_x_cleanup();

return 0;
}

PassRefPtr<DocumentFragment> createFragmentFromMarkup(Document* document, const String& markup, const String& baseURL, FragmentScriptingPermission scriptingPermission)
{
// We use a fake body element here to trick the HTML parser to using the InBody insertion mode.
RefPtr<HTMLBodyElement> fakeBody = HTMLBodyElement::create(document);
    RefPtr<DocumentFragment> fragment =  Range::createDocumentFragmentForElement(markup, fakeBody.get(), scriptingPermission);

if (fragment && !baseURL.isEmpty() && baseURL != blankURL() && baseURL != document->baseURL())
completeURLs(fragment.get(), baseURL);

return fragment.release();
}

fpAcc(TIFF* tif, uint8* cp0, tmsize_t cc)
{
tmsize_t stride = PredictorState(tif)->stride;
uint32 bps = tif->tif_dir.td_bitspersample / 8;
tmsize_t wc = cc / bps;
tmsize_t count = cc;
uint8 *cp = (uint8 *) cp0;
uint8 *tmp = (uint8 *)_TIFFmalloc(cc);

	assert((cc%(bps*stride))==0);

if (!tmp)
		return;

while (count > stride) {
REPEAT4(stride, cp[stride] =
(unsigned char) ((cp[stride] + cp[0]) & 0xff); cp++)
count -= stride;
}

_TIFFmemcpy(tmp, cp0, cc);
cp = (uint8 *) cp0;
for (count = 0; count < wc; count++) {
uint32 byte;
for (byte = 0; byte < bps; byte++) {
#if WORDS_BIGENDIAN
cp[bps * count + byte] = tmp[byte * wc + count];
#else
cp[bps * count + byte] =
tmp[(bps - byte - 1) * wc + count];
#endif
}
}
_TIFFfree(tmp);
}

