static int filter_frame(AVFilterLink *inlink, AVFrame *in)
{
GradFunContext *s = inlink->dst->priv;
AVFilterLink *outlink = inlink->dst->outputs[0];
AVFrame *out;
int p, direct;

if (av_frame_is_writable(in)) {
direct = 1;
out = in;
} else {
direct = 0;
out = ff_get_video_buffer(outlink, outlink->w, outlink->h);
if (!out) {
av_frame_free(&in);
return AVERROR(ENOMEM);
}
av_frame_copy_props(out, in);
}

    for (p = 0; p < 4 && in->data[p]; p++) {
int w = inlink->w;
int h = inlink->h;
int r = s->radius;
if (p) {
w = s->chroma_w;
h = s->chroma_h;
r = s->chroma_r;
}

if (FFMIN(w, h) > 2 * r)
filter(s, out->data[p], in->data[p], w, h, out->linesize[p], in->linesize[p], r);
else if (out->data[p] != in->data[p])
av_image_copy_plane(out->data[p], out->linesize[p], in->data[p], in->linesize[p], w, h);
}

if (!direct)
av_frame_free(&in);

return ff_filter_frame(outlink, out);
}

_PUBLIC_ bool ldap_encode(struct ldap_message *msg,
DATA_BLOB *result, TALLOC_CTX *mem_ctx)
{
struct asn1_data *data = asn1_init(mem_ctx);
int i, j;


if (!data) return false;

       asn1_push_tag(data, ASN1_SEQUENCE(0));
       asn1_write_Integer(data, msg->messageid);

switch (msg->type) {
case LDAP_TAG_BindRequest: {
struct ldap_BindRequest *r = &msg->r.BindRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_Integer(data, r->version);
               asn1_write_OctetString(data, r->dn,
                                      (r->dn != NULL) ? strlen(r->dn) : 0);

switch (r->mechanism) {
case LDAP_AUTH_MECH_SIMPLE:
/* context, primitive */
                       asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(0));
                       asn1_write(data, r->creds.password,
                                  strlen(r->creds.password));
                       asn1_pop_tag(data);
break;
case LDAP_AUTH_MECH_SASL:
/* context, constructed */
                       asn1_push_tag(data, ASN1_CONTEXT(3));
                       asn1_write_OctetString(data, r->creds.SASL.mechanism,
                                              strlen(r->creds.SASL.mechanism));
if (r->creds.SASL.secblob) {
                               asn1_write_OctetString(data, r->creds.SASL.secblob->data,
                                                      r->creds.SASL.secblob->length);
}
                       asn1_pop_tag(data);
break;
default:
                       return false;
}

               asn1_pop_tag(data);
break;
}
case LDAP_TAG_BindResponse: {
struct ldap_BindResponse *r = &msg->r.BindResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, &r->response);
if (r->SASL.secblob) {
                       asn1_write_ContextSimple(data, 7, r->SASL.secblob);
}
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_UnbindRequest: {
/*             struct ldap_UnbindRequest *r = &msg->r.UnbindRequest; */
               asn1_push_tag(data, ASN1_APPLICATION_SIMPLE(msg->type));
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_SearchRequest: {
struct ldap_SearchRequest *r = &msg->r.SearchRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->basedn, strlen(r->basedn));
               asn1_write_enumerated(data, r->scope);
               asn1_write_enumerated(data, r->deref);
               asn1_write_Integer(data, r->sizelimit);
               asn1_write_Integer(data, r->timelimit);
               asn1_write_BOOLEAN(data, r->attributesonly);

if (!ldap_push_filter(data, r->tree)) {
                       return false;
}

               asn1_push_tag(data, ASN1_SEQUENCE(0));
for (i=0; i<r->num_attributes; i++) {
                       asn1_write_OctetString(data, r->attributes[i],
                                              strlen(r->attributes[i]));
}
               asn1_pop_tag(data);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_SearchResultEntry: {
struct ldap_SearchResEntry *r = &msg->r.SearchResultEntry;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->dn, strlen(r->dn));
               asn1_push_tag(data, ASN1_SEQUENCE(0));
for (i=0; i<r->num_attributes; i++) {
struct ldb_message_element *attr = &r->attributes[i];
                       asn1_push_tag(data, ASN1_SEQUENCE(0));
                       asn1_write_OctetString(data, attr->name,
                                              strlen(attr->name));
                       asn1_push_tag(data, ASN1_SEQUENCE(1));
for (j=0; j<attr->num_values; j++) {
                               asn1_write_OctetString(data,
attr->values[j].data,
                                                      attr->values[j].length);
}
                       asn1_pop_tag(data);
                       asn1_pop_tag(data);
}
               asn1_pop_tag(data);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_SearchResultDone: {
struct ldap_Result *r = &msg->r.SearchResultDone;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ModifyRequest: {
struct ldap_ModifyRequest *r = &msg->r.ModifyRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->dn, strlen(r->dn));
               asn1_push_tag(data, ASN1_SEQUENCE(0));

for (i=0; i<r->num_mods; i++) {
struct ldb_message_element *attrib = &r->mods[i].attrib;
                       asn1_push_tag(data, ASN1_SEQUENCE(0));
                       asn1_write_enumerated(data, r->mods[i].type);
                       asn1_push_tag(data, ASN1_SEQUENCE(0));
                       asn1_write_OctetString(data, attrib->name,
                                              strlen(attrib->name));
                       asn1_push_tag(data, ASN1_SET);
for (j=0; j<attrib->num_values; j++) {
                               asn1_write_OctetString(data,
attrib->values[j].data,
                                                      attrib->values[j].length);

}
                       asn1_pop_tag(data);
                       asn1_pop_tag(data);
                       asn1_pop_tag(data);
}

               asn1_pop_tag(data);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ModifyResponse: {
struct ldap_Result *r = &msg->r.ModifyResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_AddRequest: {
struct ldap_AddRequest *r = &msg->r.AddRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->dn, strlen(r->dn));
               asn1_push_tag(data, ASN1_SEQUENCE(0));

for (i=0; i<r->num_attributes; i++) {
struct ldb_message_element *attrib = &r->attributes[i];
                       asn1_push_tag(data, ASN1_SEQUENCE(0));
                       asn1_write_OctetString(data, attrib->name,
                                              strlen(attrib->name));
                       asn1_push_tag(data, ASN1_SET);
for (j=0; j<r->attributes[i].num_values; j++) {
                               asn1_write_OctetString(data,
attrib->values[j].data,
                                                      attrib->values[j].length);
}
                       asn1_pop_tag(data);
                       asn1_pop_tag(data);
}
               asn1_pop_tag(data);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_AddResponse: {
struct ldap_Result *r = &msg->r.AddResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_DelRequest: {
struct ldap_DelRequest *r = &msg->r.DelRequest;
               asn1_push_tag(data, ASN1_APPLICATION_SIMPLE(msg->type));
               asn1_write(data, r->dn, strlen(r->dn));
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_DelResponse: {
struct ldap_Result *r = &msg->r.DelResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ModifyDNRequest: {
struct ldap_ModifyDNRequest *r = &msg->r.ModifyDNRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->dn, strlen(r->dn));
               asn1_write_OctetString(data, r->newrdn, strlen(r->newrdn));
               asn1_write_BOOLEAN(data, r->deleteolddn);
if (r->newsuperior) {
                       asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(0));
                       asn1_write(data, r->newsuperior,
                                  strlen(r->newsuperior));
                       asn1_pop_tag(data);
}
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ModifyDNResponse: {
struct ldap_Result *r = &msg->r.ModifyDNResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_CompareRequest: {
struct ldap_CompareRequest *r = &msg->r.CompareRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->dn, strlen(r->dn));
               asn1_push_tag(data, ASN1_SEQUENCE(0));
               asn1_write_OctetString(data, r->attribute,
                                      strlen(r->attribute));
               asn1_write_OctetString(data, r->value.data,
                                      r->value.length);
               asn1_pop_tag(data);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_CompareResponse: {
struct ldap_Result *r = &msg->r.ModifyDNResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_AbandonRequest: {
struct ldap_AbandonRequest *r = &msg->r.AbandonRequest;
               asn1_push_tag(data, ASN1_APPLICATION_SIMPLE(msg->type));
               asn1_write_implicit_Integer(data, r->messageid);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_SearchResultReference: {
struct ldap_SearchResRef *r = &msg->r.SearchResultReference;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->referral, strlen(r->referral));
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ExtendedRequest: {
struct ldap_ExtendedRequest *r = &msg->r.ExtendedRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(0));
               asn1_write(data, r->oid, strlen(r->oid));
               asn1_pop_tag(data);
if (r->value) {
                       asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(1));
                       asn1_write(data, r->value->data, r->value->length);
                       asn1_pop_tag(data);
}
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ExtendedResponse: {
struct ldap_ExtendedResponse *r = &msg->r.ExtendedResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, &r->response);
if (r->oid) {
                       asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(10));
                       asn1_write(data, r->oid, strlen(r->oid));
                       asn1_pop_tag(data);
}
if (r->value) {
                       asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(11));
                       asn1_write(data, r->value->data, r->value->length);
                       asn1_pop_tag(data);
}
               asn1_pop_tag(data);
break;
}
default:
               return false;
}

if (msg->controls != NULL) {
               asn1_push_tag(data, ASN1_CONTEXT(0));

for (i = 0; msg->controls[i] != NULL; i++) {
if (!ldap_encode_control(mem_ctx, data,
msg->controls[i])) {
msg->controls[i])) {
DEBUG(0,("Unable to encode control %s\n",
msg->controls[i]->oid));
                               return false;
}
}

               asn1_pop_tag(data);
}

       asn1_pop_tag(data);
       if (data->has_error) {
               asn1_free(data);
               return false;
       }

*result = data_blob_talloc(mem_ctx, data->data, data->length);
asn1_free(data);
return true;
}

static const char *blob2string_talloc(TALLOC_CTX *mem_ctx,
char *result = talloc_array(mem_ctx, char, blob.length+1);
memcpy(result, blob.data, blob.length);
result[blob.length] = '\0';
return result;
}

void BackgroundLoaderOffliner::StartSnapshot() {
if (!pending_request_.get()) {
DVLOG(1) << "Pending request was cleared during delay.";
return;
}
DCHECK(is_low_bar_met_)
<< "Minimum quality must have been reached before saving a snapshot";

// Add this signal to signal_data_.
AddLoadingSignal("Snapshotting");

SavePageRequest request(*pending_request_.get());
// If there was an error navigating to page, return loading failed.
if (page_load_state_ != SUCCESS) {
Offliner::RequestStatus status;
switch (page_load_state_) {
case RETRIABLE_NET_ERROR:
status = Offliner::RequestStatus::LOADING_FAILED_NET_ERROR;
break;
case RETRIABLE_HTTP_ERROR:
status = Offliner::RequestStatus::LOADING_FAILED_HTTP_ERROR;
break;
case NONRETRIABLE:
status = Offliner::RequestStatus::LOADING_FAILED_NO_RETRY;
break;
default:
// We should've already checked for Success before entering here.
NOTREACHED();
status = Offliner::RequestStatus::LOADING_FAILED;
}

std::move(completion_callback_).Run(request, status);
ResetState();
return;
}

content::WebContents* web_contents(
content::WebContentsObserver::web_contents());

Offliner::RequestStatus loaded_page_error =
CanSavePageInBackground(web_contents);
if (loaded_page_error != Offliner::RequestStatus::UNKNOWN) {
std::move(completion_callback_).Run(request, loaded_page_error);
ResetState();
return;
}

save_state_ = SAVING;

// Capture loading signals to UMA.
RequestStats& image_stats = stats_[ResourceDataType::IMAGE];
RequestStats& css_stats = stats_[ResourceDataType::TEXT_CSS];
RequestStats& xhr_stats = stats_[ResourceDataType::XHR];
  bool image_complete = (image_stats.requested == image_stats.completed);
  bool css_complete = (css_stats.requested == css_stats.completed);
  bool xhr_complete = (xhr_stats.requested == xhr_stats.completed);
  RecordResourceCompletionUMA(image_complete, css_complete, xhr_complete);

// Add loading signal into the MHTML that will be generated if the command
// line flag is set for it.
if (IsOfflinePagesLoadSignalCollectingEnabled()) {
// Write resource percentage signal data into extra data before emitting it
// to the MHTML.
signal_data_.SetDouble("StartedImages", image_stats.requested);
signal_data_.SetDouble("CompletedImages", image_stats.completed);
signal_data_.SetDouble("StartedCSS", css_stats.requested);
signal_data_.SetDouble("CompletedCSS", css_stats.completed);
signal_data_.SetDouble("StartedXHR", xhr_stats.requested);
signal_data_.SetDouble("CompletedXHR", xhr_stats.completed);

// Stash loading signals for writing when we write out the MHTML.
std::string headers = base::StringPrintf(
"%s\r\n%s\r\n\r\n", kContentTransferEncodingBinary, kXHeaderForSignals);
std::string body;
base::JSONWriter::Write(signal_data_, &body);
std::string content_type = kContentType;
std::string content_location = base::StringPrintf(
"cid:signal-data-%" PRId64 "@mhtml.blink", request.request_id());

content::MHTMLExtraParts* extra_parts =
content::MHTMLExtraParts::FromWebContents(web_contents);
DCHECK(extra_parts);
if (extra_parts != nullptr) {
extra_parts->AddExtraMHTMLPart(content_type, content_location, headers,
body);
}
}

std::unique_ptr<OfflinePageArchiver> archiver(new OfflinePageMHTMLArchiver());

OfflinePageModel::SavePageParams params;
params.url = web_contents->GetLastCommittedURL();
params.client_id = request.client_id();
params.proposed_offline_id = request.request_id();
params.is_background = true;
params.use_page_problem_detectors = true;
params.request_origin = request.request_origin();

// Pass in the original URL if it's different from last committed
// when redirects occur.
if (!request.original_url().is_empty())
params.original_url = request.original_url();
else if (params.url != request.url())
params.original_url = request.url();

offline_page_model_->SavePage(
params, std::move(archiver), web_contents,
base::Bind(&BackgroundLoaderOffliner::OnPageSaved,
weak_ptr_factory_.GetWeakPtr()));
}

static opj_bool pi_next_rpcl(opj_pi_iterator_t * pi)
{
    opj_pi_comp_t *comp = NULL;
    opj_pi_resolution_t *res = NULL;
    long index = 0;

    if (!pi->first) {
        goto LABEL_SKIP;
    } else {
        int compno, resno;
        pi->first = 0;
        pi->dx = 0;
        pi->dy = 0;
        for (compno = 0; compno < pi->numcomps; compno++) {
            comp = &pi->comps[compno];
            for (resno = 0; resno < comp->numresolutions; resno++) {
                int dx, dy;
                res = &comp->resolutions[resno];
                dx = comp->dx * (1 << (res->pdx + comp->numresolutions - 1 - resno));
                dy = comp->dy * (1 << (res->pdy + comp->numresolutions - 1 - resno));
                pi->dx = !pi->dx ? dx : int_min(pi->dx, dx);
                pi->dy = !pi->dy ? dy : int_min(pi->dy, dy);
            }
        }
    }
    if (!pi->tp_on) {
        pi->poc.ty0 = pi->ty0;
        pi->poc.tx0 = pi->tx0;
        pi->poc.ty1 = pi->ty1;
        pi->poc.tx1 = pi->tx1;
    }
    for (pi->resno = pi->poc.resno0; pi->resno < pi->poc.resno1; pi->resno++) {
        for (pi->y = pi->poc.ty0; pi->y < pi->poc.ty1;
                pi->y += pi->dy - (pi->y % pi->dy)) {
            for (pi->x = pi->poc.tx0; pi->x < pi->poc.tx1;
                    pi->x += pi->dx - (pi->x % pi->dx)) {
                for (pi->compno = pi->poc.compno0; pi->compno < pi->poc.compno1; pi->compno++) {
                    int levelno;
                    int trx0, try0;
                    int trx1, try1;
                    int rpx, rpy;
                    int prci, prcj;
                    comp = &pi->comps[pi->compno];
                    if (pi->resno >= comp->numresolutions) {
                        continue;
                    }
                    res = &comp->resolutions[pi->resno];
                    levelno = comp->numresolutions - 1 - pi->resno;
                    trx0 = int_ceildiv(pi->tx0, comp->dx << levelno);
                    try0 = int_ceildiv(pi->ty0, comp->dy << levelno);
                    trx1 = int_ceildiv(pi->tx1, comp->dx << levelno);
                     try1 = int_ceildiv(pi->ty1, comp->dy << levelno);
                     rpx = res->pdx + levelno;
                     rpy = res->pdy + levelno;
                     if (!((pi->y % (comp->dy << rpy) == 0) || ((pi->y == pi->ty0) &&
                             ((try0 << levelno) % (1 << rpy))))) {
                         continue;
                    }
                    if (!((pi->x % (comp->dx << rpx) == 0) || ((pi->x == pi->tx0) &&
                            ((trx0 << levelno) % (1 << rpx))))) {
                        continue;
                    }

                    if ((res->pw == 0) || (res->ph == 0)) {
                        continue;
                    }

                    if ((trx0 == trx1) || (try0 == try1)) {
                        continue;
                    }

                    prci = int_floordivpow2(int_ceildiv(pi->x, comp->dx << levelno), res->pdx)
                           - int_floordivpow2(trx0, res->pdx);
                    prcj = int_floordivpow2(int_ceildiv(pi->y, comp->dy << levelno), res->pdy)
                           - int_floordivpow2(try0, res->pdy);
                    pi->precno = prci + prcj * res->pw;
                    for (pi->layno = pi->poc.layno0; pi->layno < pi->poc.layno1; pi->layno++) {
                        index = pi->layno * pi->step_l + pi->resno * pi->step_r + pi->compno *
                                pi->step_c + pi->precno * pi->step_p;
                        if (!pi->include[index]) {
                            pi->include[index] = 1;
                            return OPJ_TRUE;
                        }
LABEL_SKIP:
                        ;
                    }
                }
            }
        }
    }

    return OPJ_FALSE;
}

