void FragmentPaintPropertyTreeBuilder::UpdatePerspective() {
DCHECK(properties_);

if (NeedsPaintPropertyUpdate()) {
if (NeedsPerspective(object_)) {
const ComputedStyle& style = object_.StyleRef();
// The perspective node must not flatten (else nothing will get
// perspective), but it should still extend the rendering context as
// most transform nodes do.
TransformPaintPropertyNode::State state;
state.matrix.ApplyPerspective(style.Perspective());
state.origin = PerspectiveOrigin(ToLayoutBox(object_)) +
ToLayoutSize(context_.current.paint_offset);
state.flattens_inherited_transform =
context_.current.should_flatten_inherited_transform;
if (RuntimeEnabledFeatures::SlimmingPaintV2Enabled() ||
RuntimeEnabledFeatures::BlinkGenPropertyTreesEnabled())
state.rendering_context_id = context_.current.rendering_context_id;
      OnUpdate(properties_->UpdatePerspective(context_.current.transform,
std::move(state)));
} else {
OnClear(properties_->ClearPerspective());
}
}

if (properties_->Perspective()) {
context_.current.transform = properties_->Perspective();
context_.current.should_flatten_inherited_transform = false;
}
}

long Block::Parse(const Cluster* pCluster) {
if (pCluster == NULL)
return -1;

if (pCluster->m_pSegment == NULL)
return -1;

assert(m_start >= 0);
assert(m_size >= 0);
assert(m_track <= 0);
assert(m_frames == NULL);
assert(m_frame_count <= 0);

long long pos = m_start;
const long long stop = m_start + m_size;

long len;

IMkvReader* const pReader = pCluster->m_pSegment->m_pReader;

m_track = ReadUInt(pReader, pos, len);

if (m_track <= 0)
return E_FILE_FORMAT_INVALID;

if ((pos + len) > stop)
return E_FILE_FORMAT_INVALID;

pos += len; // consume track number

if ((stop - pos) < 2)
return E_FILE_FORMAT_INVALID;

long status;
long long value;

status = UnserializeInt(pReader, pos, 2, value);

if (status)
return E_FILE_FORMAT_INVALID;

if (value < SHRT_MIN)
return E_FILE_FORMAT_INVALID;

if (value > SHRT_MAX)
return E_FILE_FORMAT_INVALID;

m_timecode = static_cast<short>(value);

pos += 2;

if ((stop - pos) <= 0)
return E_FILE_FORMAT_INVALID;

status = pReader->Read(pos, 1, &m_flags);

if (status)
return E_FILE_FORMAT_INVALID;

const int lacing = int(m_flags & 0x06) >> 1;

++pos; // consume flags byte

if (lacing == 0) { // no lacing
if (pos > stop)

return E_FILE_FORMAT_INVALID;

m_frame_count = 1;
    m_frames = new Frame[m_frame_count];

Frame& f = m_frames[0];
f.pos = pos;

const long long frame_size = stop - pos;

    if (frame_size > LONG_MAX)
return E_FILE_FORMAT_INVALID;

f.len = static_cast<long>(frame_size);

return 0; // success
}

if (pos >= stop)
return E_FILE_FORMAT_INVALID;

unsigned char biased_count;

status = pReader->Read(pos, 1, &biased_count);

if (status)

return E_FILE_FORMAT_INVALID;

++pos;  // consume frame count
  assert(pos <= stop);

m_frame_count = int(biased_count) + 1;

  m_frames = new Frame[m_frame_count];
  assert(m_frames);

if (lacing == 1) {  // Xiph
Frame* pf = m_frames;
Frame* const pf_end = pf + m_frame_count;

    long size = 0;
int frame_count = m_frame_count;

while (frame_count > 1) {
long frame_size = 0;

for (;;) {
unsigned char val;

if (pos >= stop)
return E_FILE_FORMAT_INVALID;

status = pReader->Read(pos, 1, &val);

if (status)
return E_FILE_FORMAT_INVALID;

++pos; // consume xiph size byte

frame_size += val;

if (val < 255)
break;
}


Frame& f = *pf++;
assert(pf < pf_end);

f.pos = 0;  // patch later

f.len = frame_size;
size += frame_size;  // contribution of this frame

--frame_count;
}

    assert(pf < pf_end);
    assert(pos <= stop);

{
Frame& f = *pf++;

if (pf != pf_end)
return E_FILE_FORMAT_INVALID;

f.pos = 0; // patch later

const long long total_size = stop - pos;

if (total_size < size)
return E_FILE_FORMAT_INVALID;


const long long frame_size = total_size - size;

      if (frame_size > LONG_MAX)
return E_FILE_FORMAT_INVALID;

f.len = static_cast<long>(frame_size);
}

pf = m_frames;
while (pf != pf_end) {

Frame& f = *pf++;
assert((pos + f.len) <= stop);

f.pos = pos;
pos += f.len;
}

assert(pos == stop);
} else if (lacing == 2) {  // fixed-size lacing
const long long total_size = stop - pos;

if ((total_size % m_frame_count) != 0)
return E_FILE_FORMAT_INVALID;


const long long frame_size = total_size / m_frame_count;

    if (frame_size > LONG_MAX)
return E_FILE_FORMAT_INVALID;

Frame* pf = m_frames;
Frame* const pf_end = pf + m_frame_count;


while (pf != pf_end) {
assert((pos + frame_size) <= stop);

Frame& f = *pf++;

f.pos = pos;
f.len = static_cast<long>(frame_size);

pos += frame_size;

}

assert(pos == stop);
} else {
assert(lacing == 3);  // EBML lacing

if (pos >= stop)
return E_FILE_FORMAT_INVALID;

    long size = 0;
int frame_count = m_frame_count;

long long frame_size = ReadUInt(pReader, pos, len);

    if (frame_size < 0)
return E_FILE_FORMAT_INVALID;

if (frame_size > LONG_MAX)
return E_FILE_FORMAT_INVALID;

if ((pos + len) > stop)
return E_FILE_FORMAT_INVALID;

pos += len; // consume length of size of first frame

if ((pos + frame_size) > stop)
return E_FILE_FORMAT_INVALID;

Frame* pf = m_frames;
Frame* const pf_end = pf + m_frame_count;

{
Frame& curr = *pf;

curr.pos = 0; // patch later

curr.len = static_cast<long>(frame_size);
size += curr.len; // contribution of this frame
}

--frame_count;

while (frame_count > 1) {
if (pos >= stop)

return E_FILE_FORMAT_INVALID;

assert(pf < pf_end);

const Frame& prev = *pf++;
assert(prev.len == frame_size);
if (prev.len != frame_size)

return E_FILE_FORMAT_INVALID;

assert(pf < pf_end);

Frame& curr = *pf;

curr.pos = 0; // patch later

const long long delta_size_ = ReadUInt(pReader, pos, len);

if (delta_size_ < 0)
return E_FILE_FORMAT_INVALID;

if ((pos + len) > stop)

return E_FILE_FORMAT_INVALID;

pos += len;  // consume length of (delta) size
      assert(pos <= stop);

const int exp = 7 * len - 1;
const long long bias = (1LL << exp) - 1LL;
const long long delta_size = delta_size_ - bias;


frame_size += delta_size;

      if (frame_size < 0)
return E_FILE_FORMAT_INVALID;

if (frame_size > LONG_MAX)
return E_FILE_FORMAT_INVALID;

curr.len = static_cast<long>(frame_size);
size += curr.len; // contribution of this frame


--frame_count;
}

    {
      assert(pos <= stop);
      assert(pf < pf_end);

const Frame& prev = *pf++;
assert(prev.len == frame_size);
if (prev.len != frame_size)
return E_FILE_FORMAT_INVALID;

      assert(pf < pf_end);

Frame& curr = *pf++;
      assert(pf == pf_end);

curr.pos = 0;  // patch later

const long long total_size = stop - pos;

if (total_size < size)
return E_FILE_FORMAT_INVALID;


frame_size = total_size - size;

      if (frame_size > LONG_MAX)
return E_FILE_FORMAT_INVALID;

curr.len = static_cast<long>(frame_size);
}

pf = m_frames;

while (pf != pf_end) {
Frame& f = *pf++;
assert((pos + f.len) <= stop);

f.pos = pos;
pos += f.len;
}

    assert(pos == stop);
}

return 0;  // success
}

void uverbs_user_mmap_disassociate(struct ib_uverbs_file *ufile)
{
	struct rdma_umap_priv *priv, *next_priv;

	lockdep_assert_held(&ufile->hw_destroy_rwsem);

	while (1) {
		struct mm_struct *mm = NULL;

		/* Get an arbitrary mm pointer that hasn't been cleaned yet */
		mutex_lock(&ufile->umap_lock);
		while (!list_empty(&ufile->umaps)) {
			int ret;

			priv = list_first_entry(&ufile->umaps,
						struct rdma_umap_priv, list);
			mm = priv->vma->vm_mm;
			ret = mmget_not_zero(mm);
			if (!ret) {
				list_del_init(&priv->list);
				mm = NULL;
				continue;
			}
			break;
		}
		mutex_unlock(&ufile->umap_lock);
		if (!mm)
			return;

		/*
		 * The umap_lock is nested under mmap_sem since it used within
		 * the vma_ops callbacks, so we have to clean the list one mm
		 * at a time to get the lock ordering right. Typically there
 		 * will only be one mm, so no big deal.
 		 */
 		down_write(&mm->mmap_sem);
 		mutex_lock(&ufile->umap_lock);
 		list_for_each_entry_safe (priv, next_priv, &ufile->umaps,
 					  list) {
			struct vm_area_struct *vma = priv->vma;

			if (vma->vm_mm != mm)
				continue;
			list_del_init(&priv->list);

			zap_vma_ptes(vma, vma->vm_start,
				     vma->vm_end - vma->vm_start);
 			vma->vm_flags &= ~(VM_SHARED | VM_MAYSHARE);
 		}
 		mutex_unlock(&ufile->umap_lock);
 		up_write(&mm->mmap_sem);
 		mmput(mm);
 	}
}

int ff_amf_get_field_value(const uint8_t *data, const uint8_t *data_end,
const uint8_t *name, uint8_t *dst, int dst_size)
{
int namelen = strlen(name);
int len;

    while (*data != AMF_DATA_TYPE_OBJECT && data < data_end) {
        len = ff_amf_tag_size(data, data_end);
        if (len < 0)
            len = data_end - data;
        data += len;
}
    if (data_end - data < 3)
return -1;
    data++;
for (;;) {
        int size = bytestream_get_be16(&data);
if (!size)
break;
        if (size < 0 || size >= data_end - data)
return -1;
        data += size;
        if (size == namelen && !memcmp(data-size, name, namelen)) {
            switch (*data++) {
case AMF_DATA_TYPE_NUMBER:
                snprintf(dst, dst_size, "%g", av_int2double(AV_RB64(data)));
break;
case AMF_DATA_TYPE_BOOL:
                snprintf(dst, dst_size, "%s", *data ? "true" : "false");
break;
case AMF_DATA_TYPE_STRING:
                len = bytestream_get_be16(&data);
                av_strlcpy(dst, data, FFMIN(len+1, dst_size));
break;
default:
return -1;
}
return 0;
}
        len = ff_amf_tag_size(data, data_end);
        if (len < 0 || len >= data_end - data)
return -1;
        data += len;
}
return -1;
}

static void v9fs_read(void *opaque)
{
int32_t fid;
uint64_t off;
ssize_t err = 0;
int32_t count = 0;
size_t offset = 7;
uint32_t max_count;
V9fsFidState *fidp;
V9fsPDU *pdu = opaque;
V9fsState *s = pdu->s;

err = pdu_unmarshal(pdu, offset, "dqd", &fid, &off, &max_count);
if (err < 0) {
goto out_nofid;
}
trace_v9fs_read(pdu->tag, pdu->id, fid, off, max_count);

fidp = get_fid(pdu, fid);
if (fidp == NULL) {
err = -EINVAL;
goto out_nofid;
}
if (fidp->fid_type == P9_FID_DIR) {

if (off == 0) {
v9fs_co_rewinddir(pdu, fidp);
}
count = v9fs_do_readdir_with_stat(pdu, fidp, max_count);
if (count < 0) {
err = count;
goto out;
}
err = pdu_marshal(pdu, offset, "d", count);
if (err < 0) {
goto out;
}
err += offset + count;
} else if (fidp->fid_type == P9_FID_FILE) {
QEMUIOVector qiov_full;
QEMUIOVector qiov;
int32_t len;

v9fs_init_qiov_from_pdu(&qiov_full, pdu, offset + 4, max_count, false);
qemu_iovec_init(&qiov, qiov_full.niov);
do {
qemu_iovec_reset(&qiov);
qemu_iovec_concat(&qiov, &qiov_full, count, qiov_full.size - count);
if (0) {
print_sg(qiov.iov, qiov.niov);
}
/* Loop in case of EINTR */
do {
len = v9fs_co_preadv(pdu, fidp, qiov.iov, qiov.niov, off);
if (len >= 0) {
off   += len;
count += len;
}
} while (len == -EINTR && !pdu->cancelled);
if (len < 0) {
/* IO error return the error */
err = len;
                goto out;
}
} while (count < max_count && len > 0);
err = pdu_marshal(pdu, offset, "d", count);
if (err < 0) {
            goto out;
}
err += offset + count;
qemu_iovec_destroy(&qiov);
qemu_iovec_destroy(&qiov_full);
} else if (fidp->fid_type == P9_FID_XATTR) {
} else {
err = -EINVAL;
}
trace_v9fs_read_return(pdu->tag, pdu->id, count, err);
out:
put_fid(pdu, fidp);
out_nofid:
pdu_complete(pdu, err);
}

static int readContigStripsIntoBuffer (TIFF* in, uint8* buf)
{
uint8* bufp = buf;
int32  bytes_read = 0;
        uint16 strip, nstrips   = TIFFNumberOfStrips(in);
uint32 stripsize = TIFFStripSize(in);
uint32 rows = 0;
uint32 rps = TIFFGetFieldDefaulted(in, TIFFTAG_ROWSPERSTRIP, &rps);
tsize_t scanline_size = TIFFScanlineSize(in);

if (scanline_size == 0) {
TIFFError("", "TIFF scanline size is zero!");
return 0;
}

for (strip = 0; strip < nstrips; strip++) {
bytes_read = TIFFReadEncodedStrip (in, strip, bufp, -1);
rows = bytes_read / scanline_size;
if ((strip < (nstrips - 1)) && (bytes_read != (int32)stripsize))
TIFFError("", "Strip %d: read %lu bytes, strip size %lu",
(int)strip + 1, (unsigned long) bytes_read,
(unsigned long)stripsize);

if (bytes_read < 0 && !ignore) {
TIFFError("", "Error reading strip %lu after %lu rows",
(unsigned long) strip, (unsigned long)rows);
return 0;
}
bufp += bytes_read;
}

return 1;
} /* end readContigStripsIntoBuffer */

int exfat_mount(struct exfat* ef, const char* spec, const char* options)
{
int rc;
enum exfat_mode mode;

exfat_tzset();
memset(ef, 0, sizeof(struct exfat));

parse_options(ef, options);

if (match_option(options, "ro"))
mode = EXFAT_MODE_RO;
else if (match_option(options, "ro_fallback"))
mode = EXFAT_MODE_ANY;
else
mode = EXFAT_MODE_RW;
ef->dev = exfat_open(spec, mode);
if (ef->dev == NULL)
return -EIO;
if (exfat_get_mode(ef->dev) == EXFAT_MODE_RO)
{
if (mode == EXFAT_MODE_ANY)
ef->ro = -1;
else
ef->ro = 1;
}

ef->sb = malloc(sizeof(struct exfat_super_block));
if (ef->sb == NULL)
{
exfat_close(ef->dev);
exfat_error("failed to allocate memory for the super block");
return -ENOMEM;
}
memset(ef->sb, 0, sizeof(struct exfat_super_block));

if (exfat_pread(ef->dev, ef->sb, sizeof(struct exfat_super_block), 0) < 0)
{
exfat_close(ef->dev);
free(ef->sb);
exfat_error("failed to read boot sector");
return -EIO;
}
if (memcmp(ef->sb->oem_name, "EXFAT   ", 8) != 0)
{
exfat_close(ef->dev);
free(ef->sb);
exfat_error("exFAT file system is not found");
return -EIO;
}
ef->zero_cluster = malloc(CLUSTER_SIZE(*ef->sb));
if (ef->zero_cluster == NULL)
{
exfat_close(ef->dev);
free(ef->sb);
exfat_error("failed to allocate zero sector");
return -ENOMEM;
}
/* use zero_cluster as a temporary buffer for VBR checksum verification */
if (!verify_vbr_checksum(ef->dev, ef->zero_cluster, SECTOR_SIZE(*ef->sb)))
{
free(ef->zero_cluster);
exfat_close(ef->dev);
free(ef->sb);
return -EIO;
}
memset(ef->zero_cluster, 0, CLUSTER_SIZE(*ef->sb));
if (ef->sb->version.major != 1 || ef->sb->version.minor != 0)
{
free(ef->zero_cluster);
exfat_close(ef->dev);
exfat_error("unsupported exFAT version: %hhu.%hhu",
ef->sb->version.major, ef->sb->version.minor);
free(ef->sb);
return -EIO;
}
if (ef->sb->fat_count != 1)
{
free(ef->zero_cluster);
exfat_close(ef->dev);
exfat_error("unsupported FAT count: %hhu", ef->sb->fat_count);
free(ef->sb);
return -EIO;
}
	/* officially exFAT supports cluster size up to 32 MB *
	if ((int) ef->sb->sector_bits + (int) ef->sb->spc_bits > 25)
	{
		free(ef->zero_cluster);
		exfat_close(ef->dev);
		exfat_error("too big cluster size: 2^%d",
				(int) ef->sb->sector_bits + (int) ef->sb->spc_bits);
		free(ef->sb);
		return -EIO;
	}
if (le64_to_cpu(ef->sb->sector_count) * SECTOR_SIZE(*ef->sb) >
exfat_get_size(ef->dev))
{
/* this can cause I/O errors later but we don't fail mounting to let
user rescue data */
exfat_warn("file system is larger than underlying device: "
"%"PRIu64" > %"PRIu64,
le64_to_cpu(ef->sb->sector_count) * SECTOR_SIZE(*ef->sb),
exfat_get_size(ef->dev));
}

ef->root = malloc(sizeof(struct exfat_node));
if (ef->root == NULL)
{
free(ef->zero_cluster);
exfat_close(ef->dev);
free(ef->sb);
exfat_error("failed to allocate root node");
return -ENOMEM;
}
memset(ef->root, 0, sizeof(struct exfat_node));
ef->root->flags = EXFAT_ATTRIB_DIR;
ef->root->start_cluster = le32_to_cpu(ef->sb->rootdir_cluster);
ef->root->fptr_cluster = ef->root->start_cluster;
ef->root->name[0] = cpu_to_le16('\0');
ef->root->size = rootdir_size(ef);
if (ef->root->size == 0)
{
free(ef->root);
free(ef->zero_cluster);
exfat_close(ef->dev);
free(ef->sb);
return -EIO;
}
/* exFAT does not have time attributes for the root directory */
ef->root->mtime = 0;
ef->root->atime = 0;
/* always keep at least 1 reference to the root node */
exfat_get_node(ef->root);

rc = exfat_cache_directory(ef, ef->root);
if (rc != 0)
goto error;
if (ef->upcase == NULL)
{
exfat_error("upcase table is not found");
goto error;
}
if (ef->cmap.chunk == NULL)
{
exfat_error("clusters bitmap is not found");
goto error;
}

if (prepare_super_block(ef) != 0)
goto error;

return 0;

error:
exfat_put_node(ef, ef->root);
exfat_reset_cache(ef);
free(ef->root);
free(ef->zero_cluster);
exfat_close(ef->dev);
free(ef->sb);
return -EIO;
}

bool MessageLoop::DoWork() {
  if (!nestable_tasks_allowed_) {
// Task can't be executed right now.
return false;
}

for (;;) {
ReloadWorkQueue();
if (work_queue_.empty())
break;

// Execute oldest task.
do {
PendingTask pending_task = std::move(work_queue_.front());
work_queue_.pop();

if (pending_task.task.IsCancelled()) {
#if defined(OS_WIN)
DecrementHighResTaskCountIfNeeded(pending_task);
#endif
} else if (!pending_task.delayed_run_time.is_null()) {
int sequence_num = pending_task.sequence_num;
TimeTicks delayed_run_time = pending_task.delayed_run_time;
AddToDelayedWorkQueue(std::move(pending_task));
// If we changed the topmost task, then it is time to reschedule.
if (delayed_work_queue_.top().sequence_num == sequence_num)
pump_->ScheduleDelayedWork(delayed_run_time);
} else {
if (DeferOrRunPendingTask(std::move(pending_task)))
return true;
}
} while (!work_queue_.empty());
}

// Nothing happened.
return false;
}

void ChromeContentBrowserClient::AppendExtraCommandLineSwitches(
CommandLine* command_line, int child_process_id) {
#if defined(USE_LINUX_BREAKPAD)
if (IsCrashReporterEnabled()) {
command_line->AppendSwitchASCII(switches::kEnableCrashReporter,
child_process_logging::GetClientId() + "," + base::GetLinuxDistro());
}
#elif defined(OS_MACOSX)
if (IsCrashReporterEnabled()) {
command_line->AppendSwitchASCII(switches::kEnableCrashReporter,
child_process_logging::GetClientId());
}
#endif  // OS_MACOSX

if (logging::DialogsAreSuppressed())
command_line->AppendSwitch(switches::kNoErrorDialogs);

std::string process_type =
command_line->GetSwitchValueASCII(switches::kProcessType);
const CommandLine& browser_command_line = *CommandLine::ForCurrentProcess();
if (process_type == switches::kExtensionProcess ||
process_type == switches::kRendererProcess) {
FilePath user_data_dir =
browser_command_line.GetSwitchValuePath(switches::kUserDataDir);
if (!user_data_dir.empty())
command_line->AppendSwitchPath(switches::kUserDataDir, user_data_dir);
#if defined(OS_CHROMEOS)
const std::string& login_profile =
browser_command_line.GetSwitchValueASCII(switches::kLoginProfile);
if (!login_profile.empty())
command_line->AppendSwitchASCII(switches::kLoginProfile, login_profile);
#endif

RenderProcessHost* process = RenderProcessHost::FromID(child_process_id);

PrefService* prefs = process->profile()->GetPrefs();
// Currently this pref is only registered if applied via a policy.
if (prefs->HasPrefPath(prefs::kDisable3DAPIs) &&
prefs->GetBoolean(prefs::kDisable3DAPIs)) {
// Turn this policy into a command line switch.
command_line->AppendSwitch(switches::kDisable3DAPIs);
}

// Disable client-side phishing detection in the renderer if it is disabled
// in the Profile preferences or the browser process.
if (!prefs->GetBoolean(prefs::kSafeBrowsingEnabled) ||
!g_browser_process->safe_browsing_detection_service()) {
command_line->AppendSwitch(switches::kDisableClientSidePhishingDetection);
}

static const char* const kSwitchNames[] = {
switches::kAllowHTTPBackgroundPage,
switches::kAllowScriptingGallery,
switches::kAppsCheckoutURL,
switches::kAppsGalleryURL,
switches::kCloudPrintServiceURL,
switches::kDebugPrint,
#if defined(GOOGLE_CHROME_BUILD) && !defined(OS_CHROMEOS) && !defined(OS_MACOSX)
// Enabled by default in Google Chrome builds, except on CrOS.
switches::kDisablePrintPreview,
#else
// Disabled by default in Chromium builds and on CrOS.
switches::kEnablePrintPreview,
#endif
switches::kDomAutomationController,
switches::kDumpHistogramsOnExit,
switches::kEnableClickToPlay,
switches::kEnableCrxlessWebApps,
switches::kEnableExperimentalExtensionApis,
switches::kEnableInBrowserThumbnailing,
switches::kEnableIPCFuzzing,
switches::kEnableNaCl,
switches::kEnableRemoting,
switches::kEnableResourceContentSettings,
switches::kEnableSearchProviderApiV2,
switches::kEnableWatchdog,
switches::kExperimentalSpellcheckerFeatures,
switches::kMemoryProfiling,
switches::kMessageLoopHistogrammer,
switches::kPpapiFlashArgs,
switches::kPpapiFlashInProcess,
switches::kPpapiFlashPath,
switches::kPpapiFlashVersion,
switches::kProfilingAtStart,
switches::kProfilingFile,
switches::kProfilingFlush,
      switches::kRemoteShellPort,
switches::kSilentDumpOnDCHECK,
};

command_line->CopySwitchesFrom(browser_command_line, kSwitchNames,
arraysize(kSwitchNames));
} else if (process_type == switches::kUtilityProcess) {
if (browser_command_line.HasSwitch(
switches::kEnableExperimentalExtensionApis)) {
command_line->AppendSwitch(switches::kEnableExperimentalExtensionApis);
}
} else if (process_type == switches::kPluginProcess) {
static const char* const kSwitchNames[] = {
#if defined(OS_CHROMEOS)
switches::kLoginProfile,
#endif
switches::kMemoryProfiling,
switches::kSilentDumpOnDCHECK,
switches::kUserDataDir,
};

command_line->CopySwitchesFrom(browser_command_line, kSwitchNames,
arraysize(kSwitchNames));
} else if (process_type == switches::kZygoteProcess) {
static const char* const kSwitchNames[] = {
switches::kEnableRemoting,
switches::kUserDataDir,  // Make logs go to the right file.
// Load (in-process) Pepper plugins in-process in the zygote pre-sandbox.
switches::kPpapiFlashInProcess,
switches::kPpapiFlashPath,
switches::kPpapiFlashVersion,
};

command_line->CopySwitchesFrom(browser_command_line, kSwitchNames,
arraysize(kSwitchNames));
}
}

