tt_sbit_decoder_load_image( TT_SBitDecoder  decoder,
FT_UInt         glyph_index,
FT_Int          x_pos,
FT_Int          y_pos )
{
/*
*  First, we find the correct strike range that applies to this
*  glyph index.
*/

FT_Byte*  p          = decoder->eblc_base + decoder->strike_index_array;
FT_Byte*  p_limit    = decoder->eblc_limit;
FT_ULong  num_ranges = decoder->strike_index_count;
FT_UInt   start, end, index_format, image_format;
FT_ULong  image_start = 0, image_end = 0, image_offset;


for ( ; num_ranges > 0; num_ranges-- )
{
start = FT_NEXT_USHORT( p );
end   = FT_NEXT_USHORT( p );

if ( glyph_index >= start && glyph_index <= end )
goto FoundRange;

p += 4;  /* ignore index offset */
}
goto NoBitmap;

FoundRange:
image_offset = FT_NEXT_ULONG( p );

/* overflow check */
p = decoder->eblc_base + decoder->strike_index_array;
if ( image_offset > (FT_ULong)( p_limit - p ) )
goto Failure;

p += image_offset;
if ( p + 8 > p_limit )
goto NoBitmap;

/* now find the glyph's location and extend within the ebdt table */
index_format = FT_NEXT_USHORT( p );
image_format = FT_NEXT_USHORT( p );
image_offset = FT_NEXT_ULONG ( p );

switch ( index_format )
{
case 1: /* 4-byte offsets relative to `image_offset' */
p += 4 * ( glyph_index - start );
if ( p + 8 > p_limit )
goto NoBitmap;

image_start = FT_NEXT_ULONG( p );
image_end   = FT_NEXT_ULONG( p );

if ( image_start == image_end )  /* missing glyph */
goto NoBitmap;
break;

case 2: /* big metrics, constant image size */
{
FT_ULong  image_size;


if ( p + 12 > p_limit )
goto NoBitmap;

image_size = FT_NEXT_ULONG( p );

if ( tt_sbit_decoder_load_metrics( decoder, &p, p_limit, 1 ) )
goto NoBitmap;

image_start = image_size * ( glyph_index - start );
image_end   = image_start + image_size;
}
break;

case 3: /* 2-byte offsets relative to 'image_offset' */
p += 2 * ( glyph_index - start );
if ( p + 4 > p_limit )
goto NoBitmap;

image_start = FT_NEXT_USHORT( p );
image_end   = FT_NEXT_USHORT( p );

if ( image_start == image_end )  /* missing glyph */
goto NoBitmap;
break;

case 4: /* sparse glyph array with (glyph,offset) pairs */
{
FT_ULong  mm, num_glyphs;


if ( p + 4 > p_limit )
goto NoBitmap;

num_glyphs = FT_NEXT_ULONG( p );

/* overflow check for p + ( num_glyphs + 1 ) * 4 */
        if ( num_glyphs > (FT_ULong)( ( ( p_limit - p ) >> 2 ) - 1 ) )
goto NoBitmap;

for ( mm = 0; mm < num_glyphs; mm++ )
FT_UInt  gindex = FT_NEXT_USHORT( p );


if ( gindex == glyph_index )
{
image_start = FT_NEXT_USHORT( p );
p          += 2;
image_end   = FT_PEEK_USHORT( p );
break;
}
p += 2;
}

if ( mm >= num_glyphs )
goto NoBitmap;
}
break;

case 5: /* constant metrics with sparse glyph codes */
case 19:
{
FT_ULong  image_size, mm, num_glyphs;


if ( p + 16 > p_limit )
goto NoBitmap;

image_size = FT_NEXT_ULONG( p );

if ( tt_sbit_decoder_load_metrics( decoder, &p, p_limit, 1 ) )
goto NoBitmap;

num_glyphs = FT_NEXT_ULONG( p );

/* overflow check for p + 2 * num_glyphs */
if ( num_glyphs > (FT_ULong)( ( p_limit - p ) >> 1 ) )
goto NoBitmap;

for ( mm = 0; mm < num_glyphs; mm++ )
{
FT_UInt  gindex = FT_NEXT_USHORT( p );


if ( gindex == glyph_index )
break;
}

if ( mm >= num_glyphs )
goto NoBitmap;

image_start = image_size * mm;
image_end   = image_start + image_size;
}
break;

default:
goto NoBitmap;
}

SkBitmap GetThumbnailForBackingStore(BackingStore* backing_store) {
base::TimeTicks begin_compute_thumbnail = base::TimeTicks::Now();

SkBitmap result;

// Get the bitmap as a Skia object so we can resample it. This is a large
// allocation and we can tolerate failure here, so give up if the allocation
// fails.
skia::PlatformCanvas temp_canvas;
  if (!backing_store->CopyFromBackingStore(gfx::Rect(gfx::Point(0, 0),
                                                     backing_store->size()),
&temp_canvas))
return result;
const SkBitmap& bmp = temp_canvas.getTopPlatformDevice().accessBitmap(false);

#if defined(OS_CHROMEOS)
// On ChromeOS, the thumbnail is always half the dimensions of the
// original.
result = SkBitmapOperations::DownsampleByTwo(bmp);
#else
result = SkBitmapOperations::DownsampleByTwoUntilSize(bmp,
kThumbnailWidth,
kThumbnailHeight);

// This is a bit subtle. SkBitmaps are refcounted, but the magic
// ones in PlatformCanvas can't be assigned to SkBitmap with proper
// refcounting.  If the bitmap doesn't change, then the downsampler
// will return the input bitmap, which will be the reference to the
// weird PlatformCanvas one insetad of a regular one. To get a
// regular refcounted bitmap, we need to copy it.
if (bmp.width() == result.width() &&
bmp.height() == result.height())
bmp.copyTo(&result, SkBitmap::kARGB_8888_Config);
#endif

HISTOGRAM_TIMES(kThumbnailHistogramName,
base::TimeTicks::Now() - begin_compute_thumbnail);
return result;
}

uint NotificationsEngine::Notify(const QString &app_name, uint replaces_id,
